
////////////////////////////////////////////////////
/////////////// Asset Types ////////////////////////

export type AssetStatus =
  | "available"
  | "borrowed"
  | "repair"
  | "damaged"
  | "disposed";

export type Asset = {
  // ข้อมูลทั่วไป
  id: string;
  name: string;
  category: string;
  status: AssetStatus;
  brand: string;
  model: string;
  serialNumber: string;
  assetImage?: string;

  // สาขาและผู้รับผิดชอบ
  branchId: string;
  responsiblePersonId: number;

  // การรับประกันและค่าใช้จ่าย
  purchasePrice: number;
  purchaseDate: string;
  warrantyEndDate: string;

  // ผู้จำหน่าย
  vendorId: string;

  // QR Code / Barcode
  qrCode: string;
  barcode: string;

  // System Information
  createdAt: string;
  updatedAt: string;
  createdBy: number;
  updatedBy: number;
};

